static uint32_t inval_bucket(int32_t w, int32_t h)
{
  int32_t m = (w > h) ? w : h;

  if (m <= 8) {
    return 0;
  }
  if (m <= 16) {
    return 1;
  }
  if (m <= 24) {
    return 2;
  }
  if (m <= 32) {
    return 3;
  }
  if (m <= 48) {
    return 4;
  }
  if (m <= 64) {
    return 5;
  }
  if (m <= 128) {
    return 6;
  }
  if (m <= 256) {
    return 7;
  }
  return 8;
}

static void wp_top_reset_slot(wp_top_t *slot, const lv_obj_t *obj,
                              const lv_area_t *area, uintptr_t ra)
{
  memset(slot, 0, sizeof(*slot));
  slot->w = lv_area_get_width(area);
  slot->h = lv_area_get_height(area);
  slot->x = area->x1;
  slot->y = area->y1;
  slot->ra = ra;
  slot->kind = inval_obj_kind(obj);
  slot->obj = obj;
  snprintf(slot->txt, sizeof(slot->txt), "%s", inval_obj_text(obj));
}

static void wp_top_add(const lv_obj_t *obj, const lv_area_t *area, uintptr_t ra)
{
  int32_t w = lv_area_get_width(area);
  int32_t h = lv_area_get_height(area);
  uint32_t i;
  wp_top_t *slot = NULL;

  for (i = 0; i < s_probe.top_n; i++) {
    wp_top_t *t = &s_probe.top[i];

    if (t->w == w && t->h == h && t->x == area->x1 && t->y == area->y1 &&
        t->ra == ra) {
      slot = t;
      break;
    }
  }

  if (slot == NULL) {
    if (s_probe.top_n < WP_TOP_N) {
      slot = &s_probe.top[s_probe.top_n++];
    } else {
      /* 满了就替换当前最少的一条（粗粒度 Top N，够归因用）。 */
      slot = &s_probe.top[0];
      for (i = 1; i < WP_TOP_N; i++) {
        if (s_probe.top[i].n < slot->n) {
          slot = &s_probe.top[i];
        }
      }
    }
    wp_top_reset_slot(slot, obj, area, ra);
  }

  slot->n++;
  slot->px += (uint32_t)w * (uint32_t)h;
}

